{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is launched in a subnet named 'public-subnet', which typically auto-assigns public IPs. Without explicitly setting associate_public_ip_address to false, the instance may be exposed directly to the internet."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.web",
      "severity": "HIGH",
      "explanation": "The metadata service (IMDSv1) is enabled by default and allows unauthenticated requests, making the instance vulnerable to SSRF attacks that can steal IAM credentials. IMDSv2 requires a session token for all requests."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "No IAM instance profile is specified. While not always a direct vulnerability if no AWS API calls are made from the instance, best practice dictates using IAM roles instead of static credentials or long-lived keys, and explicit attachment ensures proper identity management."
    }
  ],
  "patched_code": "resource "aws_instance" "web" {
  ami                         = "${var.ami}"
  instance_type               = "t2.micro"
  subnet_id                   = "${aws_subnet.public-subnet.id}"
  vpc_security_group_ids      = ["${aws_security_group.sgweb.id}"]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.ec2_profile.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }
}

# Note: The following resources are added to satisfy CKV2_AWS_41 as they were missing.
# In a real scenario, these would likely exist elsewhere or need to be defined properly.
resource "aws_iam_role" "ec2_role" {
  name = "ec2-web-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "ec2-web-profile"
  role = aws_iam_role.ec2_role.name
}",
  "fix_summary": "Disabled automatic public IP assignment to reduce network exposure. Enforced IMDSv2 by requiring HTTP tokens to prevent SSRF credential theft. Added an IAM Instance Profile and Role to ensure the EC2 instance uses temporary security credentials rather than relying on implicit defaults or static keys."
}
